### Step 2: Modify Component to Handle Image Uploads

```typescript
// add-news.component.ts
import { Component } from '@angular/core';
import { FormBuilder, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { NewsService } from '../news-events.service';
import { CKEditorLoaderService } from '../ckeditor-loader.service';

@Component({
  selector: 'app-add-news',
  standalone: true,
  imports: [ReactiveFormsModule],
  templateUrl: './add-news.component.html',
  styleUrls: ['./add-news.component.scss']
})
export class AddNewsComponent {
  newsForm: FormGroup;
  public Editor: any;
  selectedFile: File | null = null;

  constructor(
    private fb: FormBuilder,
    private newsService: NewsService,
    private ckeditorLoader: CKEditorLoaderService
  ) {
    this.newsForm = this.fb.group({
      title: [''],
      content: [''],
      image: [null]
    });
  }

  async ngOnInit() {
    console.log('NewsEventsComponent init');
    if (typeof window !== 'undefined') {
      this.Editor = await this.ckeditorLoader.loadCKEditor();
    }
  }

  onFileSelected(event: any) {
    this.selectedFile = event.target.files[0] || null;
  }

  async onSubmit() {
    if (this.newsForm.valid) {
      const newsData = this.newsForm.value;
      const contentHtml = newsData.content; // This contains the HTML content from CKEditor

      let imageUrl = '';

      if (this.selectedFile) {
        const uploadResult = await this.uploadImage(this.selectedFile);
        imageUrl = uploadResult.url;
      }

      this.newsService.addNews('instituteId', {
        title: newsData.title,
        content: contentHtml,
        imageUrl: imageUrl,
        date: new Date()
      }).then(() => {
        this.newsForm.reset();
      });
    }
  }

  private async uploadImage(file: File): Promise<{ url: string }> {
    const storageRef = firebase.storage().ref();
    const fileRef = storageRef.child(`news-images/${file.name}`);
    await fileRef.put(file);
    const url = await fileRef.getDownloadURL();
    return { url };
  }
}
```

