import { Component, OnInit, Inject, PLATFORM_ID } from '@angular/core';
import { FormBuilder, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { NewsService } from '../news-events.service';
import { isPlatformBrowser } from '@angular/common';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatButtonModule } from '@angular/material/button';
import { MatCardModule } from '@angular/material/card';
import { MatSnackBar } from '@angular/material/snack-bar';
import { AngularFireAuth } from '@angular/fire/auth';
import { AngularFireStorage } from '@angular/fire/storage';

@Component({
  selector: 'app-add-news',
  standalone: true,
  imports: [
    ReactiveFormsModule,
    MatFormFieldModule,
    MatInputModule,
    MatButtonModule,
    MatCardModule
  ],
  templateUrl: './add-news.component.html',
  styleUrls: ['./add-news.component.scss']
})
export class AddNewsComponent implements OnInit {
  newsForm: FormGroup;
  public Editor: any;
  maxLength = 100; // Maximum length for the title

  constructor(
    private fb: FormBuilder,
    private newsService: NewsService,
    private afAuth: AngularFireAuth,
    private afStorage: AngularFireStorage,
    private snackBar: MatSnackBar,
    @Inject(PLATFORM_ID) private platformId: Object
  ) {
    this.newsForm = this.fb.group({
      title: [''],
      content: [''],
      image: [null]
    });
  }

  ngOnInit() {
    if (isPlatformBrowser(this.platformId)) {
      import('@ckeditor/ckeditor5-build-classic').then(ClassicEditor => {
        this.Editor = ClassicEditor.default;
        console.log('CKEditor loaded:', this.Editor);
      }).catch(error => {
        console.error('Error loading CKEditor:', error);
      });
    }
  }

  onFileSelected(event: any) {
    this.newsForm.patchValue({
      image: event.target.files[0]
    });
  }

  get remainingChars(): number {
    return this.maxLength - (this.newsForm.get('title')?.value.length || 0);
  }

  async uploadImage(file: File): Promise<string> {
    const user = await this.afAuth.currentUser;
    if (!user) {
      throw new Error('User not authenticated');
    }

    const filePath = `news-images/${file.name}`;
    const fileRef = this.afStorage.ref(filePath);
    await fileRef.put(file);
    return fileRef.getDownloadURL().toPromise();
  }

  async onSubmit() {
    if (this.newsForm.valid) {
      const newsData = this.newsForm.value;
      const contentHtml = newsData.content; // This contains the HTML content from CKEditor

      let imageUrl = '';

      if (newsData.image) {
        try {
          imageUrl = await this.uploadImage(newsData.image);
        } catch (error) {
          console.error('Image upload failed', error);
          this.snackBar.open('Image upload failed. Please try again later.', 'Close', { duration: 5000 });
          return;
        }
      }

      try {
        await this.newsService.addNews('instituteId', {
          title: newsData.title,
          content: contentHtml,
          imageUrl: imageUrl,
          date: new Date()
        });
        this.snackBar.open('News added successfully', 'Close', { duration: 5000 });
        this.newsForm.reset();
      } catch (error) {
        console.error('Failed to add news:', error);
        this.snackBar.open('Failed to add news. Please try again later.', 'Close', { duration: 5000 });
      }
    }
  }
}
