    this.renderer = rendererFactory.createRenderer(null, null);
  }

  ngOnInit() {
    setTimeout(() => {
      this.setThemeColor('#YOUR_DYNAMIC_COLOR_CODE'); // Replace with your dynamic color logic
    }, 100); // Adding a delay of 100ms
  }

  setThemeColor(color: string) {
    let metaThemeColor = document.querySelector("meta[name=theme-color]") as HTMLMetaElement;
    if (metaThemeColor) {
      this.renderer.setAttribute(metaThemeColor, 'content', color);
    } else {
      metaThemeColor = this.renderer.createElement('meta') as HTMLMetaElement;
      this.renderer.setAttribute(metaThemeColor, 'name', 'theme-color');
      this.renderer.setAttribute(metaThemeColor, 'content', color);
      this.renderer.appendChild(document.head, metaThemeColor);
    }
  }
