   ```

### Step 2: Define User Roles

Store user roles in Firestore under a `users` collection.

1. **Add User Roles to Firestore**:
   Each user document should contain a `role` field (e.g., 'student', 'parent', 'teacher').

### Step 3: Create Auth Guards

Create Angular guards to protect routes based on user roles.

1. **Create Auth Guard**:
   ```typescript
   import { Injectable } from '@angular/core';
   import { CanActivate, ActivatedRouteSnapshot, RouterStateSnapshot, Router } from '@angular/router';
   import { AngularFireAuth } from '@angular/fire/auth';
   import { AngularFirestore } from '@angular/fire/firestore';
   import { Observable } from 'rxjs';
   import { map, take, tap } from 'rxjs/operators';

   @Injectable({
     providedIn: 'root'
   })
   export class AuthGuard implements CanActivate {
     constructor(
       private afAuth: AngularFireAuth,
       private firestore: AngularFirestore,
       private router: Router
     ) {}

     canActivate(
       next: ActivatedRouteSnapshot,
       state: RouterStateSnapshot
     ): Observable<boolean> {
       return this.afAuth.authState.pipe(
         take(1),
         map(user => !!user),
         tap(loggedIn => {
           if (!loggedIn) {
             this.router.navigate(['/login']);
           }
         })
       );
     }
   }
   ```

2. **Create Role Guard**:
   ```typescript
   @Injectable({
     providedIn: 'root'
   })
   export class RoleGuard implements CanActivate {
     constructor(
       private afAuth: AngularFireAuth,
       private firestore: AngularFirestore,
       private router: Router
     ) {}

     canActivate(
       next: ActivatedRouteSnapshot,
       state: RouterStateSnapshot
     ): Observable<boolean> {
       const expectedRole = next.data.expectedRole;

       return this.afAuth.authState.pipe(
         take(1),
         map(user => user && user.uid),
         switchMap(uid => this.firestore.collection('users').doc(uid).valueChanges()),
         map((user: any) => user.role === expectedRole),
         tap(isAuthorized => {
           if (!isAuthorized) {
             this.router.navigate(['/unauthorized']);
           }
         })
       );
     }
   }
   ```

### Step 4: Restrict Access to Modules

Use guards in your routing module to protect routes.

1. **Add Guards to Routes**:
   ```typescript
   const routes: Routes = [
     { path: 'dashboard', component: DashboardComponent, canActivate: [AuthGuard] },
     { path: 'admin', component: AdminComponent, canActivate: [AuthGuard, RoleGuard], data: { expectedRole: 'admin' } },
     { path: 'teacher', component: TeacherComponent, canActivate: [AuthGuard, RoleGuard], data: { expectedRole: 'teacher' } },
     { path: 'student', component: StudentComponent, canActivate: [AuthGuard, RoleGuard], data: { expectedRole: 'student' } },
     { path: 'parent', component: ParentComponent, canActivate: [AuthGuard, RoleGuard], data: { expectedRole: 'parent' } },
     { path: 'login', component: LoginComponent },
     { path: '**', redirectTo: 'login' }
   ];

   @NgModule({
     imports: [RouterModule.forRoot(routes)],
     exports: [RouterModule]
   })
   export class AppRoutingModule { }
   ```

### Optional: Handle Unauthorized Access

Create an `UnauthorizedComponent` to handle cases where a user tries to access a restricted page.

