export class HomeComponent implements OnInit {
  obsl: string | null = null;

  constructor(private route: ActivatedRoute) {}

  ngOnInit(): void {
    // Subscribe to query parameters
    this.route.queryParams.subscribe(params => {
      this.obsl = params['obsl'];
      console.log('obsl:', this.obsl);
      // You can now use this.obsl in your component logic
    });
  }
}
```

### Explanation

1. **Import `ActivatedRoute`**:
   Import `ActivatedRoute` from `@angular/router` to gain access to the route's query parameters.

2. **Subscribe to Query Parameters**:
   In the `ngOnInit` lifecycle hook, subscribe to the `queryParams` observable provided by `ActivatedRoute`. This will allow you to access the query parameters when the component initializes or when the query parameters change.

3. **Access the Parameter**:
   The query parameters are accessible via the `params` object. In this example, `obsl` is retrieved from the URL and assigned to the `obsl` property of the component.

### HTML Template

You can now use the `obsl` property in your component template:

```html
<div *ngIf="obsl">
  <p>OBS value: {{ obsl }}</p>
</div>
