```typescript
import { Component, OnInit } from '@angular/core';
import { AngularFirestore } from '@angular/fire/firestore';
import { ActivatedRoute, Router } from '@angular/router';

@Component({
  selector: 'app-observation-list',
  templateUrl: './observation-list.component.html',
  styleUrls: ['./observation-list.component.css']
})
export class ObservationListComponent implements OnInit {
  observations: any[] = [];
  newObservation = '';
  pageUrl = '';

  constructor(private firestore: AngularFirestore, private route: ActivatedRoute, private router: Router) {}

  ngOnInit(): void {
    this.pageUrl = this.router.url; // Get the current page URL
    this.loadObservations();
  }

  loadObservations(): void {
    this.firestore.collection('observations', ref => ref.where('page', '==', this.pageUrl)).snapshotChanges().subscribe(data => {
      this.observations = data.map(e => {
        return {
          id: e.payload.doc.id,
          ...e.payload.doc.data() as any
        };
      });
    });
  }

  addObservation(): void {
    if (this.newObservation.trim()) {
      this.firestore.collection('observations').add({
        page: this.pageUrl,
        text: this.newObservation,
        completed: false
      });
      this.newObservation = '';
    }
  }

  markAsCompleted(id: string): void {
    this.firestore.collection('observations').doc(id).update({ completed: true });
  }
}
```

