To retrieve a list of institutes registered by the logged-in user and all institutes if the user is an admin, you need to perform Firestore queries based on the user's role and email.

### Step-by-Step Implementation

1. **Add a Method in `AuthService` to Fetch Institutes**:
   - Fetch institutes based on the user's email.
   - Fetch all institutes if the user is an admin.

2. **Update the `RegisterComponent` to Display the Institutes**:
   - Display the list of institutes based on the fetched data.

### Step 1: Add a Method in `AuthService` to Fetch Institutes

**auth.service.ts**:
```typescript
import { Injectable } from '@angular/core';
import { Auth, signInWithPopup, GoogleAuthProvider, signOut, UserCredential } from '@angular/fire/auth';
import { Firestore, collection, addDoc, doc, setDoc, getDoc, query, where, getDocs } from '@angular/fire/firestore';
import { authState } from 'rxfire/auth';
import { Observable } from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class AuthService {
  user$: Observable<any>;

  constructor(private auth: Auth, private firestore: Firestore) {
    this.user$ = authState(this.auth);
  }

  googleSignIn(): Promise<UserCredential> {
    return signInWithPopup(this.auth, new GoogleAuthProvider());
  }

  signOut() {
    return signOut(this.auth);
  }

  saveRegistrationData(instituteName: string, address: string, startedSince: Date | null, userEmail: string) {
    const registrationRef = collection(this.firestore, 'registrations');
    return addDoc(registrationRef, {
      instituteName,
      address,
      startedSince: startedSince ? startedSince.toISOString() : null,
      createdAt: new Date().toISOString(),
      userEmail
    });
  }

  saveInstituteData(instituteName: string, data: any) {
    const instituteRef = doc(this.firestore, `institutes/${instituteName}`);
    return setDoc(instituteRef, {
      ...data,
      startedSince: data.startedSince ? data.startedSince.toISOString() : null,
      createdAt: new Date().toISOString()
    });
  }

  async checkInstituteExists(instituteName: string): Promise<boolean> {
    const instituteRef = doc(this.firestore, `institutes/${instituteName}`);
    const docSnapshot = await getDoc(instituteRef);
    return docSnapshot.exists();
  }

  async getInstitutes(userEmail: string, isAdmin: boolean): Promise<any[]> {
    const institutes: any[] = [];
    const institutesRef = collection(this.firestore, 'institutes');
    let q;

    if (isAdmin) {
      q = institutesRef;
    } else {
      q = query(institutesRef, where('userEmail', '==', userEmail));
    }

    const querySnapshot = await getDocs(q);
    querySnapshot.forEach((doc) => {
      institutes.push({ id: doc.id, ...doc.data() });
    });

    return institutes;
  }
}
```

