}
```

3. **Ensure Your Angular Project Includes styles.scss**: Make sure your Angular project is configured to include `styles.scss`.

**angular.json:**
```json
{
  "projects": {
    "your-app-name": {
      "architect": {
        "build": {
          "options": {
            "styles": [
              "src/styles.scss"
            ]
          }
        }
      }
    }
  }
}
```

### Option 2: Dynamically Load Themes

If you want to support multiple themes (e.g., light and dark mode) and allow users to switch between them, you can dynamically load the appropriate CSS file.

1. **Add Theme CSS Files**: Place the theme CSS files in your `src/assets` folder.

**Folder structure:**
```
src/
  assets/
    themes/
      light-theme.css
      dark-theme.css
```

2. **Load Themes Dynamically in Angular**: Create a service to dynamically load the CSS files based on user preference.

**theme.service.ts:**
```typescript
import { Injectable } from '@angular/core';

@Injectable({
  providedIn: 'root'
})
export class ThemeService {
  private currentTheme: string = 'light-theme';

  constructor() {
    this.loadTheme(this.currentTheme);
  }

  loadTheme(themeName: string) {
    const head = document.getElementsByTagName('head')[0];
    const themeLink = document.getElementById('theme-link');

    if (themeLink) {
      themeLink.setAttribute('href', `assets/themes/${themeName}.css`);
    } else {
      const link = document.createElement('link');
      link.id = 'theme-link';
      link.rel = 'stylesheet';
      link.href = `assets/themes/${themeName}.css`;
      head.appendChild(link);
    }
  }

  switchTheme(themeName: string) {
    this.currentTheme = themeName;
    this.loadTheme(this.currentTheme);
  }
}
```

3. **Use the Theme Service in Your AppComponent**:

**app.component.ts:**
```typescript
import { Component } from '@angular/core';
import { ThemeService } from './theme.service';

@Component({
  selector: 'app-root',
