  standalone: true
})
export class AppComponent {
  title = 'Your App Name';

  constructor(private themeService: ThemeService) {}

  switchToLightTheme() {
    this.themeService.switchTheme('light-theme');
  }

  switchToDarkTheme() {
    this.themeService.switchTheme('dark-theme');
  }
}
```

