})
export class InstituteListComponent implements OnInit {
  institutes: any[] = [];
  user: User | null = null;

  constructor(private instituteService: InstituteService, private authService: AuthService) {}

  ngOnInit() {
    this.authService.user$.subscribe(async user => {
      if (user) {
        console.log('User logged in:', user);
        this.user = user;
        try {
          const isSuperadmin = await this.authService.isSuperadmin(user.uid);
          if (isSuperadmin) {
            console.log('User is superadmin');
            this.institutes = await this.instituteService.getAllInstitutes();
          } else {
            console.log('Fetching institutes for user:', user.email);
            this.institutes = await this.instituteService.getInstitutesByUserEmail(user.email as string);
          }
          console.log('Institutes to display:', this.institutes);
        } catch (error) {
          console.error('Error fetching institutes:', error);
        }
      } else {
        console.log('No user logged in');
      }
    });
  }
}
```

### Summary

1. **Create a Roles Collection**:
   - Create a `roles` collection in Firestore to store user roles.

2. **Add Superadmin Role**:
   - Manually add superadmin roles in Firestore for specific users.

3. **Update AuthService**:
   - Add a method to check if a user is a superadmin.

4. **Update InstituteListComponent**:
   - Use the new method to check if the logged-in user is a superadmin and fetch institutes accordingly.

By following these steps, you can manage superadmin roles in Firestore and adjust the behavior of your application based on the user's role. If you encounter any further issues or need additional assistance, feel free to ask!

