import { Injectable } from '@angular/core';
import { Firestore, collection, query, where, getDocs } from '@angular/fire/firestore';
import { Auth } from '@angular/fire/auth';

@Injectable({
  providedIn: 'root'
})
export class InstituteService {
  constructor(private firestore: Firestore, private auth: Auth) {}

  async getInstitutesByUserEmail(userEmail: string): Promise<any[]> {
    const q = query(collection(this.firestore, 'registrations'), where('userEmail', '==', userEmail));
    const querySnapshot = await getDocs(q);
    return querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
  }

  async getAllInstitutes(): Promise<any[]> {
    const q = query(collection(this.firestore, 'registrations'));
    const querySnapshot = await getDocs(q);
    return querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
  }
}
```

