    return this.afAuth.signOut();
  }

  // Sign in with Google
  googleSignIn() {
    return this.afAuth.signInWithPopup(new firebase.auth.GoogleAuthProvider());
  }

  // Get currently authenticated user
  getUser() {
    return this.afAuth.authState;
  }
}
