      console.error('User not logged in or email not available');
      return;
    }

    const instituteExists = await this.authService.checkInstituteExists(this.instituteName);
    if (instituteExists) {
      console.error('Institute name already exists');
      // You can display an error message to the user here
      return;
    }

    const startedSinceDate = this.startedSince ? this.startedSince.toDate() : null;
    this.authService.saveRegistrationData(this.instituteName, this.address, startedSinceDate, this.user.email)
      .then(() => {
        console.log('Registration data saved');
        // Save additional institute data
