#### 3. Registration Form Component Logic in Angular
```typescript
// registration.component.ts
import { Component } from '@angular/core';
import { AngularFirestore } from '@angular/fire/firestore';
import { AngularFireFunctions } from '@angular/fire/functions';

@Component({
  selector: 'app-registration',
  templateUrl: './registration.component.html',
})
export class RegistrationComponent {
  instituteName: string;
  contactEmail: string;
  desiredSubdomain: string;

  constructor(private firestore: AngularFirestore, private functions: AngularFireFunctions) {}

  async onSubmit() {
    // Save draft registration in Firestore
    await this.firestore.collection('registrationDrafts').add({
      instituteName: this.instituteName,
      contactEmail: this.contactEmail,
      desiredSubdomain: this.desiredSubdomain,
      status: 'draft',
      timestamp: new Date()
    });

    // Call Cloud Function to send notification to admin
    const callable = this.functions.httpsCallable('sendAdminNotification');
    await callable({ instituteName: this.instituteName, contactEmail: this.contactEmail });

    document.getElementById('notification').innerText = 'Registration submitted. We will contact you soon.';
  }
}
```

