const admin = require('firebase-admin');
const nodemailer = require('nodemailer');

admin.initializeApp();

const firestore = admin.firestore();
const gmailEmail = functions.config().gmail.email;
const gmailPassword = functions.config().gmail.password;

const mailTransport = nodemailer.createTransport({
  service: 'gmail',
  auth: {
    user: gmailEmail,
    pass: gmailPassword,
  },
});

exports.sendAdminNotification = functions.https.onCall(async (data, context) => {
  const { instituteName, contactEmail } = data;

  const mailOptions = {
    from: gmailEmail,
    to: 'admin@growthtutorials.in',
    subject: 'New Registration Draft Submitted',
    text: `A new registration draft has been submitted by ${instituteName}. Contact email: ${contactEmail}.`,
  };

