export class RegisterComponent implements OnInit {
  step: number = 1;
  instituteName: string = '';
  address: string = '';
  startedSince: moment.Moment | null = null;
  user: any = null;

  constructor(private authService: AuthService) {}

  ngOnInit() {
    this.authService.user$.subscribe(user => {
