      this.breakpoint = window.innerWidth;
    }
  }

  showFeature(feature: string) {
    this.selectedFeature = feature;
  }
}
```

### Explanation

1. **Imports**: Added imports for `PLATFORM_ID` and `isPlatformBrowser` from `@angular/common`.
2. **Constructor Injection**: Injected `PLATFORM_ID` in the constructor.
3. **Platform Check**: Used `isPlatformBrowser` to ensure `window.innerWidth` is only accessed in the browser environment.

### Summary

By using `PLATFORM_ID` and `isPlatformBrowser`, you can safely access the `window` object without running into errors during server-side rendering or other non-browser environments. This approach ensures that your code is compatible with Angular Universal and other scenarios where `window` might not be defined.

