import { Injectable } from '@angular/core';
import { Firestore, collection, addDoc, deleteDoc, getDocs, query, where, collectionData } from '@angular/fire/firestore';
import { getStorage, ref, uploadBytesResumable, getDownloadURL } from '@angular/fire/storage';
import { Observable } from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class NewsService {
  constructor(private firestore: Firestore) {}

  getNews(instituteId: string): Observable<any[]> {
    const newsCollection = collection(this.firestore, `institutes/${instituteId}/newsEvents`);
    const q = query(newsCollection);
    return collectionData(q, { idField: 'id' });
  }

  addNews(instituteId: string, news: any) {
    const newsCollection = collection(this.firestore, `institutes/${instituteId}/newsEvents`);
    return addDoc(newsCollection, news);
  }

  deleteNews(instituteId: string, newsId: string) {
    const newsDoc = doc(this.firestore, `institutes/${instituteId}/newsEvents/${newsId}`);
    return deleteDoc(newsDoc);
  }

  uploadImage(file: File, path: string): Promise<string> {
    const storage = getStorage();
    const storageRef = ref(storage, path);
    const uploadTask = uploadBytesResumable(storageRef, file);

    return new Promise((resolve, reject) => {
      uploadTask.on('state_changed', 
        (snapshot) => {
          // Handle upload progress
        }, 
        (error) => {
          reject(error);
        }, 
        () => {
          getDownloadURL(uploadTask.snapshot.ref).then(downloadURL => {
            resolve(downloadURL);
          });
        }
      );
    });
  }
}
```

