  ) {
    this.newsForm = this.fb.group({
      title: [''],
      content: ['']
    });
  }

  async ngOnInit() {
    if (typeof window !== 'undefined') {
      this.Editor = await this.ckeditorLoader.loadCKEditor();
      this.Editor.create(document.querySelector('#editor'), {
        extraPlugins: [this.MyCustomUploadAdapterPlugin.bind(this)]
      });
    }
  }

  MyCustomUploadAdapterPlugin(editor) {
    editor.plugins.get('FileRepository').createUploadAdapter = (loader) => {
      return new MyUploadAdapter(loader, this.storage);
    };
  }

  onSubmit() {
    if (this.newsForm.valid) {
      const newsData = this.newsForm.value;
      const contentHtml = newsData.content; // This contains the HTML content from CKEditor
      // Save contentHtml to Firestore
    }
  }
}
```

### 3. Use Angular's `isPlatformBrowser` for SSR Compatibility

Additionally, you can use Angular’s `isPlatformBrowser` to ensure code runs only in the browser.

#### Import `isPlatformBrowser`

```typescript
import { Component, OnInit, Inject, PLATFORM_ID } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { FormBuilder, FormGroup } from '@angular/forms';
import { CKEditorLoaderService } from './ckeditor-loader.service';

@Component({
  selector: 'app-add-news',
  templateUrl: './add-news.component.html',
  styleUrls: ['./add-news.component.scss']
})
export class AddNewsComponent implements OnInit {
  newsForm: FormGroup;
  public Editor: any;

  constructor(
    private fb: FormBuilder,
    private ckeditorLoader: CKEditorLoaderService,
    @Inject(PLATFORM_ID) private platformId: Object
  ) {
    this.newsForm = this.fb.group({
      title: [''],
      content: ['']
    });
  }

  async ngOnInit() {
    if (isPlatformBrowser(this.platformId)) {
      this.Editor = await this.ckeditorLoader.loadCKEditor();
      this.Editor.create(document.querySelector('#editor'), {
        extraPlugins: [this.MyCustomUploadAdapterPlugin.bind(this)]
      });
    }
  }

  MyCustomUploadAdapterPlugin(editor) {
    editor.plugins.get('FileRepository').createUploadAdapter = (loader) => {
      return new MyUploadAdapter(loader, this.storage);
    };
  }

  onSubmit() {
    if (this.newsForm.valid) {
      const newsData = this.newsForm.value;
      const contentHtml = newsData.content; // This contains the HTML content from CKEditor
      // Save contentHtml to Firestore
    }
  }
}
```

### Summary

1. **Conditional Loading**: Ensure CKEditor is loaded only in the browser environment using `typeof window !== 'undefined'`.
2. **SSR Compatibility**: Use Angular’s `isPlatformBrowser` to conditionally execute code meant for the browser.
