### Using the Async Pipe

The async pipe in Angular allows you to bind the observable directly to the template, automatically subscribing to the observable and unsubscribing when the component is destroyed. This is particularly useful for one-time data fetches or simple data bindings.

### Updated `app.component.ts`

First, modify your service to return an observable without subscribing in the component:

```typescript
import { Injectable } from '@angular/core';
import { Firestore, collection, collectionData, query, where } from '@angular/fire/firestore';
import { Observable } from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class CustomizationService {

  constructor(private firestore: Firestore) { }

  getCustomization(subdomain: string): Observable<any[]> {
    const registrationsRef = collection(this.firestore, 'registrations');
    const q = query(registrationsRef, where('subdomain', '==', subdomain));
    return collectionData(q, { idField: 'id' });
  }
}
```

