```typescript
import { Injectable } from '@angular/core';
import { AngularFirestore } from '@angular/fire/firestore';
import { Observable } from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class NewsService {
  constructor(private firestore: AngularFirestore) {}

  getNews(instituteId: string): Observable<any[]> {
    return this.firestore.collection(`institutes/${instituteId}/newsEvents`).valueChanges();
  }

  addNews(instituteId: string, news: any) {
    const newsId = this.firestore.createId();
    return this.firestore.doc(`institutes/${instituteId}/newsEvents/${newsId}`).set(news);
  }

  deleteNews(instituteId: string, newsId: string) {
    return this.firestore.doc(`institutes/${instituteId}/newsEvents/${newsId}`).delete();
  }
}
```

#### Component for Adding News and Events

```typescript
import { Component } from '@angular/core';
import { FormBuilder, FormGroup } from '@angular/forms';
import { NewsService } from './news.service';
import { AngularFireStorage } from '@angular/fire/storage';
import { finalize } from 'rxjs/operators';

@Component({
  selector: 'app-add-news',
  templateUrl: './add-news.component.html',
  styleUrls: ['./add-news.component.css']
})
export class AddNewsComponent {
  newsForm: FormGroup;
  uploadPercent: Observable<number>;
  downloadURL: Observable<string>;

  constructor(
    private fb: FormBuilder,
    private newsService: NewsService,
    private storage: AngularFireStorage
  ) {
    this.newsForm = this.fb.group({
      title: [''],
      content: [''],
      image: [null]
    });
  }

  onSubmit() {
    if (this.newsForm.valid) {
      const newsData = this.newsForm.value;
      if (newsData.image) {
        const filePath = `news_images/${Date.now()}_${newsData.image.name}`;
        const fileRef = this.storage.ref(filePath);
        const task = this.storage.upload(filePath, newsData.image);

        this.uploadPercent = task.percentageChanges();
        task.snapshotChanges().pipe(
          finalize(() => {
            fileRef.getDownloadURL().subscribe(url => {
              newsData.imageUrl = url;
              this.newsService.addNews('instituteId', newsData).then(() => {
                this.newsForm.reset();
              });
            });
          })
        ).subscribe();
      } else {
        this.newsService.addNews('instituteId', newsData).then(() => {
          this.newsForm.reset();
        });
      }
    }
  }
}
```

