  ],
  imports: [
    BrowserModule,
    ReactiveFormsModule,
    CKEditorModule
  ],
  providers: [],
  bootstrap: [AppComponent]
})
export class AppModule { }
```

### 3. Create the Add News Component

#### add-news.component.ts

```typescript
import { Component } from '@angular/core';
import { FormBuilder, FormGroup } from '@angular/forms';
import { NewsService } from './news.service';
import { AngularFireStorage } from '@angular/fire/storage';
import { finalize } from 'rxjs/operators';

@Component({
  selector: 'app-add-news',
  templateUrl: './add-news.component.html',
  styleUrls: ['./add-news.component.css']
})
export class AddNewsComponent {
  newsForm: FormGroup;
  editorConfig = {
    toolbar: ['heading', '|', 'bold', 'italic', 'link', 'bulletedList', 'numberedList', 'blockQuote', 'imageUpload'],
    image: {
      toolbar: ['imageTextAlternative', 'imageStyle:full', 'imageStyle:side']
    }
  };

  constructor(
    private fb: FormBuilder,
    private newsService: NewsService,
    private storage: AngularFireStorage
  ) {
    this.newsForm = this.fb.group({
      title: [''],
      content: [''],
      image: [null]
    });
  }

  onSubmit() {
    if (this.newsForm.valid) {
      const newsData = this.newsForm.value;
      const contentHtml = newsData.content; // This contains the HTML content from CKEditor

      this.newsService.addNews('instituteId', {
        title: newsData.title,
        content: contentHtml,
        date: new Date()
      }).then(() => {
        this.newsForm.reset();
      });
    }
  }
}
```

#### add-news.component.html

```html
